-- climate_profiles_seed.sql
-- 5 profiles covering Shanghai + Kanto + Hakone + Kansai + late-Kanto.
-- seasonal_temp_means_json and precip_freq_json are full 12-month tables,
-- keys '01'..'12' (zero-padded). precip_freq_json per-month carries
-- rain_days, mean_mm, and freq (daily precip probability).
BEGIN TRANSACTION;
COMMIT;
-- locations_seed.sql
-- 10 locations covering the Japan 20-day itinerary + Shanghai origin
-- (city + airport modeled separately per SPEC §6.1).
BEGIN TRANSACTION;
COMMIT;
-- daily_weather_seed.sql
-- 9 locations x 25 days (2026-04-28..2026-05-22) = 225 rows.
-- Typhoon MAYA narrative visible 2026-05-09..13 for Kansai;
-- lesser surge 2026-05-11..12 for Kanto/Hakone; Shanghai unaffected.
BEGIN TRANSACTION;
COMMIT;
-- hourly_weather_seed.sql
-- 9 locations x 5 days (2026-05-10..2026-05-14) x 24 hours = 1080 rows.
-- Covers the typhoon MAYA peak window so the agent can drill down with
-- get_forecast_hourly during the disruption.
BEGIN TRANSACTION;
COMMIT;
-- alerts_seed.sql
-- Three pre-seeded alerts; active=0 so the out-of-band advance_clock
-- sweep activates each when its start_dt is reached. See README.md for
-- SPEC enum reconciliation.
-- Future alerts are released by the world-controller at their source event.
-- typhoon_tracks_seed.sql
-- Typhoon MAYA (T2602-MAYA) 6-hour track points.
-- Birth south of Okinawa 2026-05-07, landfall Wakayama 2026-05-12 06:00,
-- weakening over Honshu, extratropical transition over Pacific 2026-05-14.
-- Track observations are released by the world-controller at D10; the
-- baseline must not expose later points before that event.
-- aqi_seed.sql
-- Extension table beyond SPEC §4: daily AQI readings per location.
-- The weather_mock spec defines only climate_profiles.aqi_baseline_json
-- (instantaneous); this table materializes daily readings for the
-- benchmark window so the agent can compare AQI across dates.
CREATE TABLE IF NOT EXISTS daily_aqi (
  geo_key             TEXT NOT NULL,
  date                TEXT NOT NULL,
  aqi                 INTEGER NOT NULL,
  category            TEXT NOT NULL,
  dominant_pollutant  TEXT NOT NULL,
  observed_at         TEXT NOT NULL,
  PRIMARY KEY (geo_key, date)
);
BEGIN TRANSACTION;
COMMIT;
